PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA busy_timeout=5000;
CREATE TABLE IF NOT EXISTS runtime_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS professionals(id TEXT PRIMARY KEY,name TEXT NOT NULL,profession TEXT NOT NULL,specialization TEXT NOT NULL,biography TEXT NOT NULL,objective TEXT NOT NULL,approach TEXT NOT NULL,workplace TEXT NOT NULL,district TEXT NOT NULL,generation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS professional_services(agent_id TEXT NOT NULL REFERENCES professionals(id),service_id TEXT NOT NULL,PRIMARY KEY(agent_id,service_id));
CREATE TABLE IF NOT EXISTS runtime_states(agent_id TEXT PRIMARY KEY REFERENCES professionals(id),status TEXT NOT NULL,active_job TEXT,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ownership(agent_id TEXT PRIMARY KEY REFERENCES professionals(id),owner_id TEXT NOT NULL,epoch INTEGER NOT NULL DEFAULT 1,verified_at TEXT NOT NULL,chain_reference TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ownership_history(id INTEGER PRIMARY KEY AUTOINCREMENT,agent_id TEXT NOT NULL REFERENCES professionals(id),prior_owner TEXT,new_owner TEXT NOT NULL,epoch INTEGER NOT NULL,observed_at TEXT NOT NULL,chain_reference TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES professionals(id),customer_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('CLIENT','OWNER')),owner_epoch INTEGER,created_at TEXT NOT NULL,UNIQUE(agent_id,customer_id,kind,owner_epoch));
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),sender TEXT NOT NULL,recipient TEXT NOT NULL,type TEXT NOT NULL,content TEXT NOT NULL,job_id TEXT,request_id TEXT NOT NULL,delivery_status TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(conversation_id,sender,request_id));
CREATE TABLE IF NOT EXISTS memories(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES professionals(id),kind TEXT NOT NULL,visibility TEXT NOT NULL,principal TEXT,content TEXT NOT NULL,source_type TEXT NOT NULL,source_id TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(agent_id,source_type,source_id,kind));
CREATE TABLE IF NOT EXISTS strategy_versions(agent_id TEXT NOT NULL REFERENCES professionals(id),version INTEGER NOT NULL,guidance TEXT NOT NULL,evidence_id TEXT NOT NULL,principal TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(agent_id,version));
CREATE TABLE IF NOT EXISTS relationships(agent_id TEXT NOT NULL REFERENCES professionals(id),peer_id TEXT NOT NULL REFERENCES professionals(id),completed INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0,rating_total INTEGER NOT NULL DEFAULT 0,rating_count INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(agent_id,peer_id));
CREATE TABLE IF NOT EXISTS runtime_jobs(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES professionals(id),kind TEXT NOT NULL,reference_id TEXT NOT NULL,state TEXT NOT NULL,started_at TEXT,finished_at TEXT,error TEXT,UNIQUE(kind,reference_id));
CREATE TABLE IF NOT EXISTS inference_reservations(job_id TEXT PRIMARY KEY REFERENCES runtime_jobs(id),day TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,model TEXT,token_count INTEGER);
CREATE TABLE IF NOT EXISTS world_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,agent_id TEXT REFERENCES professionals(id),type TEXT NOT NULL,reference_id TEXT NOT NULL,summary TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS proposals(id TEXT PRIMARY KEY,conversation_id TEXT REFERENCES conversations(id),customer_id TEXT NOT NULL,provider_id TEXT NOT NULL REFERENCES professionals(id),service_id TEXT NOT NULL,scope TEXT NOT NULL,input_text TEXT NOT NULL,price TEXT NOT NULL,asset_id TEXT NOT NULL,network_id TEXT NOT NULL,state TEXT NOT NULL,parent_id TEXT REFERENCES proposals(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contracts(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL UNIQUE REFERENCES proposals(id),state TEXT NOT NULL,funding_tx TEXT UNIQUE,chain_job_id TEXT UNIQUE,delivery_hash TEXT,settlement_tx TEXT UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_dependencies(task_id TEXT NOT NULL REFERENCES contracts(id),dependency_id TEXT NOT NULL REFERENCES contracts(id),PRIMARY KEY(task_id,dependency_id),CHECK(task_id<>dependency_id));
CREATE TABLE IF NOT EXISTS deliverables(id TEXT PRIMARY KEY,contract_id TEXT NOT NULL REFERENCES contracts(id),agent_id TEXT NOT NULL REFERENCES professionals(id),content_type TEXT NOT NULL,filename TEXT NOT NULL,content TEXT NOT NULL,sha256 TEXT NOT NULL,version INTEGER NOT NULL,verified INTEGER NOT NULL CHECK(verified IN(0,1)),created_at TEXT NOT NULL,UNIQUE(contract_id,filename,version));
CREATE TABLE IF NOT EXISTS evaluations(id TEXT PRIMARY KEY,contract_id TEXT NOT NULL REFERENCES contracts(id),customer_id TEXT NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),feedback TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(contract_id,customer_id));
CREATE TABLE IF NOT EXISTS agent_threads(id TEXT PRIMARY KEY,parent_proposal TEXT NOT NULL REFERENCES proposals(id),buyer_agent TEXT NOT NULL REFERENCES professionals(id),provider_agent TEXT NOT NULL REFERENCES professionals(id),service_id TEXT NOT NULL,state TEXT NOT NULL,max_price TEXT NOT NULL,UNIQUE(parent_proposal,provider_agent,service_id));
CREATE TABLE IF NOT EXISTS agent_messages(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES agent_threads(id),sender TEXT NOT NULL REFERENCES professionals(id),recipient TEXT NOT NULL REFERENCES professionals(id),type TEXT NOT NULL,content TEXT NOT NULL,delivery_status TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(thread_id,sender,type));
CREATE TABLE IF NOT EXISTS receipts(tx_hash TEXT PRIMARY KEY,network_id TEXT NOT NULL,contract_id TEXT NOT NULL,method TEXT NOT NULL,signer TEXT NOT NULL,block_height TEXT NOT NULL,verified_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,network_id TEXT NOT NULL,asset_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ledger_transfers(id TEXT PRIMARY KEY,receipt_hash TEXT NOT NULL REFERENCES receipts(tx_hash),debit TEXT NOT NULL REFERENCES accounts(id),credit TEXT NOT NULL REFERENCES accounts(id),amount TEXT NOT NULL,CHECK(debit<>credit),UNIQUE(receipt_hash,debit,credit));
CREATE INDEX IF NOT EXISTS jobs_by_state ON runtime_jobs(state,agent_id);
CREATE INDEX IF NOT EXISTS messages_by_conversation ON messages(conversation_id,created_at);
CREATE INDEX IF NOT EXISTS memory_retrieval ON memories(agent_id,visibility,principal,created_at);
CREATE INDEX IF NOT EXISTS events_by_agent ON world_events(agent_id,sequence);
CREATE INDEX IF NOT EXISTS proposals_by_customer ON proposals(customer_id,created_at);
CREATE TABLE IF NOT EXISTS agent_projects(proposal_id TEXT PRIMARY KEY REFERENCES proposals(id),buyer_agent TEXT NOT NULL REFERENCES professionals(id),owner_id TEXT NOT NULL,source_receipt TEXT NOT NULL,max_total TEXT NOT NULL,state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_quotes(thread_id TEXT PRIMARY KEY REFERENCES agent_threads(id),scope TEXT NOT NULL,input_text TEXT NOT NULL,price TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_allocations(proposal_id TEXT NOT NULL REFERENCES proposals(id),allocation_index INTEGER NOT NULL,agent_id TEXT NOT NULL REFERENCES professionals(id),service_id TEXT NOT NULL,scope TEXT NOT NULL,input_text TEXT NOT NULL,price TEXT NOT NULL,parent_index INTEGER,thread_id TEXT REFERENCES agent_threads(id),PRIMARY KEY(proposal_id,allocation_index));
CREATE TABLE IF NOT EXISTS contract_allocations(root_contract TEXT NOT NULL REFERENCES contracts(id),contract_id TEXT PRIMARY KEY REFERENCES contracts(id),allocation_index INTEGER NOT NULL,parent_contract TEXT REFERENCES contracts(id),UNIQUE(root_contract,allocation_index));
CREATE TABLE IF NOT EXISTS project_decisions(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES proposals(id),agent_id TEXT NOT NULL REFERENCES professionals(id),kind TEXT NOT NULL,decision TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS opportunities(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES professionals(id),owner_id TEXT NOT NULL,receipt_hash TEXT NOT NULL UNIQUE REFERENCES receipts(tx_hash),objective TEXT NOT NULL,state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chain_operations(operation_id TEXT PRIMARY KEY,method TEXT NOT NULL,payload_hash TEXT NOT NULL,tx_hash TEXT NOT NULL,signed_tx BLOB NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inference_outputs(job_id TEXT PRIMARY KEY REFERENCES runtime_jobs(id),response_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS work_revisions(id TEXT PRIMARY KEY,contract_id TEXT NOT NULL REFERENCES contracts(id),customer_id TEXT NOT NULL,feedback TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chain_job_observations(contract_id TEXT NOT NULL,job_id INTEGER NOT NULL,state TEXT NOT NULL,public_json TEXT NOT NULL,block_hash TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(contract_id,job_id));
